Prove the following statement in the context of the given problem:
If $S$ and $T$ are two strings, then the length of the longest common prefix between $S$ and $T$ is less than or equal to the length of the first match found in the computation, and the length of the longest common substring is less than or equal to the length of the prefix obtained.

Solution by the downstream LLM:
```d
function maxCommonPref(string S, string T) returns (string, integer, integer) {
    // Find the length of the longest common prefix
    let prefixLength = -1;
    let i = 0;
    while (i < min(S.length, T.length) && S.charAt(i) == T.charAt(i)) {
        prefixLength++;
        i++;
    }

    // Return the length of the longest common substring
    let substringLength = i;
    for (j := substringLength; j < S.length; j++) {
        if (S.charAt(j) == T.charAt(j)) {
            if (j - i > prefixLength) {
                prefixLength = j - i;  // Update prefix length if current match is longer
            }
        } else if (prefixLength > 0) {
            prefixLength--;         // Decrease prefix length if a mismatch is found
        }
    }
    return (prefixLength, substringLength);
}
