    // Find the length of the longest common prefix
    let prefixLength = 0;
    let i = 0;
    while (i < S.length && i < T.length && S.charAt(i) == T.charAt(i)) {
        prefixLength++;
        i++;
    }

    // Find the length of the longest common substring
    let substringLength = prefixLength;
    let j = substringLength;
    while (j < S.length && j < T.length && S.charAt(j) == T.charAt(j)) {
        if (j == S.length - prefixLength) {
            substringLength = S.length - (j + 1);
        } else if (j + 1 < T.length && S.charAt(j) == T.charAt(j + 1)) {
            substringLength = S.length - (j + 1);
        }
        j++;
    }

    return (S.substring(0, prefixLength), S.substring(0, substringLength));
}
```

